import json,re
from pathlib import Path
files=[Path(f).resolve().relative_to(Path.cwd()).as_posix() for f in json.loads(Path('graphify-out/.files_04.json').read_text(encoding='utf-8-sig'))]
nodes={};edges=[];texts={f:Path(f).read_text(encoding='utf-8-sig') for f in files}
def cid(s):return 'dayz_'+re.sub('[^a-z0-9]+','_',s.lower()).strip('_')
def loc(f,word):
    lines=texts[f].splitlines()
    for i,line in enumerate(lines):
        if word.lower() in line.lower():return 'line '+str(i+1)
    return 'line 1'
def node(label,f,why=None):
    k=cid(label)
    if k not in nodes:nodes[k]=dict(id=k,label=label,file_type='rationale',source_file=f,source_location=loc(f,label),source_url=None,captured_at=None,author=None,contributor=None)
    if why:nodes[k]['rationale']=why
    return k
def edge(a,b,f,relation='references',why=None,confidence='EXTRACTED',score=1.0):
    d=dict(source=a,target=b,relation=relation,confidence=confidence,confidence_score=score,source_file=f,source_location=loc(f,why or nodes.get(a,{}).get('label','')),weight=1.0)
    if why:d['description']=why
    edges.append(d)
