for f,(labels,relations) in zip(files,specs):
    title=next(x[2:].strip() for x in texts[f].splitlines() if x.startswith('# '))
    doc='doc_'+re.sub('[^a-z0-9]+','_',f.lower()).strip('_')
    nodes[doc]=dict(id=doc,label=title,file_type='document',source_file=f,source_location='line 1',source_url=None,captured_at=None,author=None,contributor=None)
    for label in labels.split('|'):edge(doc,node(label,f),f)
    for a,b,r,why in relations:
        if (a,b) in [('RestApi','JsonFileLoader'),('LanternCore','LNT_BanManager')]:continue
        ak=node(a,f);bk=node(b,f)
        edge(ak,bk,f,r,why)
        edges[-1]['source_location']=loc(f,a)
        if edges[-1]['source_location']=='line 1':edges[-1]['source_location']=loc(f,b)
    for match in re.finditer(r'\[[^\]]+\]\(([^)#]+\.md)(?:#[^)]*)?\)',texts[f]):
        target=(Path(f).parent/match.group(1)).resolve()
        try:rel=target.relative_to(Path.cwd()).as_posix()
        except ValueError:continue
        if rel not in files or rel==f:continue
        td='doc_'+re.sub('[^a-z0-9]+','_',rel.lower()).strip('_')
        edge(doc,td,f,'references','Explicit internal chapter link')
        edges[-1]['source_location']='line '+str(texts[f][:match.start()].count('\n')+1)

# Cross-cutting similarities are interpretive and individually scored.
for a,b,i,score,why in [
('ParticleManager','Widget Pooling',5,.88,'Both amortize creation cost through reusable pools, across rendering effects and UI'),
('PluginRecipesManager','CCmdRegistry',20,.84,'Both discover named operations through registries before validating and executing them'),
('ConstructionPart','LNT_PermNode',14,.66,'Both encode parent/dependency structure, but construction requirements differ from permission inheritance')]:
    edge(cid(a),cid(b),files[i],'semantically_similar_to',why,'INFERRED',score)

for label,i,why in [
('SEffectManager',0,'One-shot effects require autodestroy and entity loops require explicit stop, preventing retained registry entries.'),
('ParticleManager',5,'Pool owns ParticleSource lifetime; render effects on clients and clean high-level SEffectManager registrations.'),
('LNT_ModuleManager',11,'Typed server and client modules avoid double update dispatch on listen servers; centralized cleanup bounds mission state.'),
('LNT_RPC',12,'Namespace plus function name separates routes within the router; handlers register early and validate authority server-side.'),
('ScriptInvoker',15,'Pair Insert with Remove and document callback signatures; teardown order requires null checks.'),
('Widget Pooling',16,'Reuse rows and debounce searches to avoid repeated widget allocation during UI refresh.'),
('ChatInputMenu',20,'Intercept completed slash-command input before vanilla ChatPlayer broadcast; route authoritative execution to server.')]:node(label,files[i],why)

# Preserve explicitly conflicting documentation as review questions, not asserted APIs.
for label,i,why,a,b in [
('Config initialization guidance conflict',11,'Module lifecycle rules forbid config loading in OnInit, while the same chapter self-loading plugin example performs it there. Startup policy needs reconciliation.','LNT_AutoConfigPlugin','LNT_ModuleBase'),
('Crafting registration guidance conflict',18,'Custom item tutorial suggests CfgRecipes config registration; the dedicated crafting chapter specifies RecipeBase subclasses and RegisterRecipies. Treat this tutorial suggestion as unresolved.','CfgRecipes','RecipeBase')]:
    ak=node(a,files[i],why);bk=node(b,files[i]);edge(ak,bk,files[i],'conceptually_related_to',why,'AMBIGUOUS',.2)
    edges[-1]['source_location']=loc(files[i],a)

hyperedges=[]
for n,label,ls,i in [
('sound_pipeline','Configured sound to live wave','CfgSoundShaders|CfgSoundSets|SoundParams|SoundObjectBuilder|SoundObject|AbstractSoundScene|AbstractWave',0),
('crafting_pipeline','Recipe discovery validation and timed execution','CraftingManager|PluginRecipesManager|RecipeBase|ActionWorldCraft|CAContinuousCraft',1),
('admin_roundtrip','Admin player-info request authorization response and UI update','AdminDemoPanel|AdminDemoConfig|AdminDemoRPC|PlayerBase|DayZGame|RPCSingleParam',19)]:
    hyperedges.append(dict(id='chunk04_'+n,label=label,nodes=[cid(s) for s in ls.split('|')],relation='participate_in',confidence='EXTRACTED',confidence_score=1.0,source_file=files[i]))

assert len(specs)==len(files)==21
assert all(e['source'] in nodes and e['target'] in nodes for e in edges)
assert all(x in nodes for h in hyperedges for x in h['nodes'])
dedup={}
for e in edges:dedup.setdefault((e['source'],e['target'],e['relation'],e['source_file'],e['confidence']),e)
out=dict(nodes=list(nodes.values()),edges=list(dedup.values()),hyperedges=hyperedges,input_tokens=0,output_tokens=0)
Path('graphify-out/.graphify_chunk_04.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'nodes':len(nodes),'edges':len(dedup),'hyperedges':len(hyperedges),'documents':21}))
